def transform(grid):
    out = [row[:] for row in grid]
    rows = [r for r in range(len(grid)) if 5 in grid[r]]
    cols = [c for c in range(len(grid[0])) if any(grid[r][c] == 5 for r in range(len(grid)))]
    top, bottom = min(rows), max(rows)
    left, right = min(cols), max(cols)

    mid_r = (top + bottom) / 2
    mid_c = (left + right) / 2
    markers = [
        (r, c, grid[r][c])
        for r in range(len(grid))
        for c in range(len(grid[0]))
        if grid[r][c] not in (0, 5)
    ]

    inner_rows = list(range(top + 1, bottom))
    inner_cols = list(range(left + 1, right))
    half_r = len(inner_rows) // 2
    half_c = len(inner_cols) // 2

    for r, c, color in markers:
        top_half = r < mid_r
        left_half = c < mid_c
        for rr in range(top + 1, bottom):
            for cc in range(left + 1, right):
                cell_top = rr < top + 1 + half_r
                cell_left = cc < left + 1 + half_c
                if (cell_top == top_half and cell_left == left_half) or (
                    cell_top != top_half and cell_left != left_half
                ):
                    out[rr][cc] = color
    return out
